package com.eliel.asistente

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.Base64

/** Sprite strip cropped from the user-approved NEXO concept image: five expressions. */
internal object NexoGraphicSprite {
    private const val DATA = ""
    val bitmap: Bitmap? by lazy {
        runCatching {
            BitmapFactory.decodeByteArray(Base64.decode(DATA, Base64.DEFAULT), 0,
                Base64.decode(DATA, Base64.DEFAULT).size)
        }.getOrNull()
    }
}
